/**
 * Reader for the committed RV64 differential fixtures.
 *
 * The fixtures are generated by tools/isa/build-rv64-fixtures.ts against
 * qemu-riscv64 and then checked in, so the differential suite runs on any
 * machine and in CI without Docker. Regenerating them needs the oracle;
 * trusting them does not.
 */
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
export const FIXTURE_DIR = join(HERE, 'fixtures')

export interface FixtureIndex {
  generator: string
  codegen: string
  oracle: string
  target: string
  march: string
  flags: string
  randomGenerator: string
  /** Seeds of the randomised programs, so a failure is reproducible by name. */
  randomSeeds: number[]
  fixtures: { name: string; steps: number; seed?: number }[]
}

export function readIndex(): FixtureIndex {
  return JSON.parse(readFileSync(join(FIXTURE_DIR, 'index.json'), 'utf8')) as FixtureIndex
}

export function fixtureNames(): string[] {
  return readIndex().fixtures.map((f) => f.name)
}

export function readElf(name: string): Uint8Array {
  return new Uint8Array(readFileSync(join(FIXTURE_DIR, `${name}.elf`)))
}

export function readObjdump(name: string): string {
  return readFileSync(join(FIXTURE_DIR, `${name}.objdump.txt`), 'utf8')
}

/** The guest's own architectural state dump; layout mirrors tools/isa/rv64/harness.h. */
export interface GuestDump {
  x: bigint[]
  f: bigint[]
  fcsr: bigint
  scratch: Uint8Array
}

export const DUMP_BYTES = 1552
const SCRATCH_BYTES = 1024

export function readDump(name: string): GuestDump {
  return decodeDump(new Uint8Array(readFileSync(join(FIXTURE_DIR, `${name}.final.bin`))))
}

export function decodeDump(bytes: Uint8Array): GuestDump {
  if (bytes.length !== DUMP_BYTES) {
    throw new Error(`guest dump is ${bytes.length} bytes, expected ${DUMP_BYTES}`)
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  const x: bigint[] = []
  const f: bigint[] = []
  for (let i = 0; i < 32; i++) x.push(view.getBigUint64(i * 8, true))
  for (let i = 0; i < 32; i++) f.push(view.getBigUint64(256 + i * 8, true))
  return {
    x,
    f,
    fcsr: view.getBigUint64(512, true),
    scratch: bytes.slice(528, 528 + SCRATCH_BYTES),
  }
}

export interface LockstepStep {
  pc: bigint
  x: bigint[]
}

/**
 * Expands the delta-encoded lockstep file back into full per-step state.
 *
 * Returned lazily as an iterator: `call` is seventeen thousand steps and the
 * larger programs a later milestone will add are far longer, so materialising
 * thirty-two bigints per step is avoidable work.
 */
export function* readLockstep(name: string): Generator<LockstepStep> {
  const text = readFileSync(join(FIXTURE_DIR, `${name}.lockstep.txt`), 'utf8')
  const state: bigint[] = Array.from({ length: 32 }, () => 0n)
  // Tolerate CRLF as well as LF. .gitattributes pins these files to LF, but a
  // fixture regenerated on a host that ignores it must still parse rather than
  // fold a stray carriage return into the last register on every line.
  for (const line of text.split(/\r?\n/)) {
    if (line.length === 0 || line.startsWith('#')) continue
    const parts = line.split(' ')
    const pc = BigInt(`0x${parts[0]!}`)
    for (let i = 1; i < parts.length; i++) {
      const field = parts[i]!
      const equals = field.indexOf('=')
      state[Number(field.slice(1, equals))] = BigInt(`0x${field.slice(equals + 1)}`)
    }
    yield { pc, x: state }
  }
}

/** The architectural state the reference started from, for seeding a run. */
export function initialState(name: string): LockstepStep {
  for (const step of readLockstep(name)) return { pc: step.pc, x: [...step.x] }
  throw new Error(`${name}: lockstep fixture is empty`)
}
